WITH ins AS (INSERT INTO sais_resources (resource_id, family_key, document_number, resource_category, subcategory, jurisdiction_level, jurisdiction, organization_name, organization_type, service_type, official_url, official_contact, statutory_authority, verification_status, last_verified_at, notes, revision) VALUES 
('SAIS-PS-009-02', 'systemic_abuse_intelligence', 409, 'campus_safety', 'campus_written_rights_notification', 'federal', 'federal -- NATIONWIDE', 'Written Notification of Rights and Options -- A Legal Obligation, Not a Courtesy', 'educational_institution | federal_agency', 'campus_written_rights_notification', 'https://ope.ed.gov/campussafety/', 'Your school''s Title IX Coordinator | Campus police or security | ED Campus Safety and Security data | RAINN: 800-656-4673', 'Clery Act, victim rights notification (20 U.S.C. sec. 1092(f)(8)) | Title IX (20 U.S.C. sec. 1681; 34 CFR Part 106) | FERPA (20 U.S.C. sec. 1232g) | Campus SaVE Act provisions | State campus victim rights statutes.', 'VERIFIED', '2026-08-17', 'ASK WHO IS CONFIDENTIAL BEFORE YOU DISCLOSE. Campus counselors generally are; resident advisors, coaches, and most faculty generally are NOT -- they are responsible employees who must report to the Title IX Coordinator, which starts a process you may not have chosen. And if nobody handed you a written notification of rights, that omission is itself a Clery Act violation worth documenting. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-009 | pipeline: Campus Safety] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 651f5d8cb18de179484f5522feec366f4381bfebec4c7bfa4d17ea9600ec93da]', 'v1.0'),
('SAIS-PS-009-03', 'systemic_abuse_intelligence', 409, 'campus_safety', 'campus_grievance_process', 'federal', 'federal -- NATIONWIDE', 'Formal Complaint, Informal Resolution, or Neither', 'educational_institution', 'campus_grievance_process', 'https://www.ed.gov/ocr', 'Your school''s Title IX Coordinator | ED Office for Civil Rights | RAINN: 800-656-4673 | Local legal aid via lsc.gov', 'Title IX (20 U.S.C. sec. 1681; 34 CFR Part 106) | Grievance procedure requirements (34 CFR 106.45) | Retaliation prohibition (34 CFR 106.71) | Clery Act (20 U.S.C. sec. 1092(f)) | FERPA (20 U.S.C. sec. 1232g)', 'VERIFIED', '2026-08-17', 'THE OCR 180-DAY CLOCK RUNS WHILE THE CAMPUS PROCESS IS PENDING -- a school investigation does not pause it, and students routinely lose the federal complaint waiting for an internal outcome. If you are nearing 180 days, file with OCR in parallel. Also: you may bring an ADVISOR OF YOUR CHOICE, including an attorney, and the school may not restrict who that is. [address_resolution: Resolve via 211.org or findhelp.org; input = ZIP code. Both return the street address, hours, and intake requirements for the specific local provider serving that ZIP.] [doc_code: PS-009 | pipeline: Campus Safety] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 14d827ea04608b9e0a27041d79f2386f796b39e474ee3f107a8007c98bb39d0d]', 'v1.0'),
('SAIS-PS-009-04', 'systemic_abuse_intelligence', 409, 'campus_safety', 'campus_evidence_and_medical_care', 'federal + state', 'federal + state -- ALL_STATES', 'Preserving Evidence and Getting Care Without Committing to a Report', 'healthcare_provider | law_enforcement', 'campus_evidence_and_medical_care', 'https://www.rainn.org/', 'RAINN National Sexual Assault Hotline: 800-656-4673 | Local rape crisis center via RAINN | Campus health center | 911 for emergencies', 'VAWA forensic exam payment provisions (34 U.S.C. sec. 10449; 34 U.S.C. sec. 12291) | Debbie Smith Act (34 U.S.C. sec. 40701 et seq.) | Survivors'' Bill of Rights Act (18 U.S.C. sec. 3772) -- federal cases | Preservation of records (18 U.S.C. sec. 2703(f)) | State anonymous kit statutes.', 'VERIFIED', '2026-08-17', 'A FORENSIC EXAM IS FREE AND DOES NOT REQUIRE YOU TO REPORT TO POLICE OR COOPERATE WITH ANYONE. Federal law guarantees both. Ask about an ANONYMOUS or non-report kit if you are not ready to decide -- it is held for years in many states. And ask the school IN WRITING to preserve surveillance video and card-access logs; those are gone in 7-30 days and nobody preserves them unless asked. [address_resolution: Resolve via HRSA findahealthcenter.hrsa.gov for sliding-scale sites; input = ZIP. For a specific provider, use the state licensing registry.] [doc_code: PS-009 | pipeline: Campus Safety] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 6d378e1cac9d62f6e9c6807bb2ab62112ed17d997f02a9941a791cbe73a4cbcd]', 'v1.0'),
('SAIS-PS-009-05', 'systemic_abuse_intelligence', 409, 'campus_safety', 'campus_k12_safety', 'federal + state', 'federal + state -- ALL_STATES', 'K-12 Schools -- Bullying, Harassment, and the Special Education Overlay', 'educational_institution | state_agency', 'campus_k12_safety', 'https://www.ed.gov/ocr', 'Your district''s Title IX Coordinator | ED Office for Civil Rights | Your state education agency | Parent Training and Information Center via parentcenterhub.org', 'Title IX (20 U.S.C. sec. 1681) | Title VI (42 U.S.C. sec. 2000d) | Section 504 (29 U.S.C. sec. 794) | IDEA (20 U.S.C. sec. 1400 et seq.; manifestation determination at sec. 1415(k)) | ADA Title II (42 U.S.C. sec. 12131) | State anti-bullying statutes.', 'VERIFIED', '2026-08-17', 'PUT EVERY COMPLAINT IN WRITING AND ESCALATE IN ORDER -- verbal complaints to a teacher are how districts later claim they had no notice. And if the child has an IEP or 504 plan, bullying that interferes with their education can be a denial of FAPE, which opens far stronger rights than the anti-bullying statute alone. Request the team meeting in writing; if they are being disciplined for disability-related behavior, demand a MANIFESTATION DETERMINATION REVIEW within 10 school days. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-009 | pipeline: Campus Safety] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 368d7b9bf9df2a5d6e9bb1e6abca86a1f0394d522af75baa1b396ba9281965b0]', 'v1.0'),
('SAIS-PS-009-06', 'systemic_abuse_intelligence', 409, 'campus_safety', 'campus_parallel_remedies', 'federal + state', 'federal + state -- ALL_STATES', 'Parallel Tracks -- Protective Orders, Federal Complaints, and Civil Claims', 'state_court | federal_agency | state_agency', 'campus_parallel_remedies', 'https://www.ed.gov/ocr', 'Your local court clerk | ED Office for Civil Rights | Your state crime victim compensation program | Your state bar lawyer referral service', 'Title IX private right of action (Cannon v. University of Chicago; Gebser; Davis) | Title IX (20 U.S.C. sec. 1681) | Clery Act (20 U.S.C. sec. 1092(f)) | Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | Full faith and credit for protection orders (18 U.S.C. sec. 2265) | State civil protection order statutes.', 'VERIFIED', '2026-08-17', 'GET A COURT PROTECTION ORDER RATHER THAN RELYING ON A CAMPUS NO-CONTACT DIRECTIVE. The campus version is administrative and police cannot enforce it; a court order is enforceable everywhere, carries criminal consequences, and follows you off campus and after graduation. And file with OCR before 180 days even if the campus process is unfinished -- the clock does not stop for the school. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-009 | pipeline: Campus Safety] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e83dc54962ec56d83ed0641cfc5413f8275f7963b524253e80ed92b5b288f24d]', 'v1.0'),
('SAIS-PS-010-01', 'systemic_abuse_intelligence', 410, 'workplace_violence', 'workplace_violence_immediate_safety', 'federal + state', 'federal + state -- ALL_STATES', 'Immediate Safety -- Reporting, Refusal Rights, and What Happens First', 'federal_agency | law_enforcement', 'workplace_violence_immediate_safety', 'https://www.osha.gov/workplace-violence', '911 for immediate danger | Federal OSHA: 800-321-6742 | Your state OSHA plan -- see jurisdiction table | VictimConnect: 855-484-2846', 'Occupational Safety and Health Act, General Duty Clause (29 U.S.C. sec. 654(a)(1)) | Right to refuse imminent danger (29 CFR 1977.12(b)(2)) | Anti-retaliation (29 U.S.C. sec. 660(c)) | State OSHA plan statutes | State laws barring retaliation for calling emergency services.', 'VERIFIED', '2026-08-17', 'CALL 911 FIRST IF THERE IS AN IMMEDIATE THREAT -- an employer policy requiring internal reporting first does not override that. Then report the hazard to the employer IN WRITING and file with OSHA, asking that your identity be kept CONFIDENTIAL. And watch the shortest clock in this pipeline: the OSHA retaliation complaint under section 11(c) is 30 DAYS from the retaliatory act. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-010 | pipeline: Workplace Violence] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 8cf9d68e53935d649a76a2edeac6f3b1bf57059c35ac9f46909de18d34dbf739]', 'v1.0'),
('SAIS-PS-010-02', 'systemic_abuse_intelligence', 410, 'workplace_violence', 'workplace_violence_employer_duty', 'federal + state', 'federal + state -- ALL_STATES', 'Employer Obligations -- The General Duty Clause and State Prevention Mandates', 'federal_agency | state_agency', 'workplace_violence_employer_duty', 'https://www.osha.gov/workplace-violence/standards', 'Federal OSHA: 800-321-6742 | Your state OSHA plan -- see jurisdiction table | Your state labor department', 'General Duty Clause (29 U.S.C. sec. 654(a)(1)) | OSHA recordkeeping (29 CFR Part 1904) | Fatality and severe injury reporting (29 CFR 1904.39) -- 8 hours for a fatality, 24 hours for hospitalization, amputation, or eye loss | State workplace violence prevention mandates.', 'VERIFIED', '2026-08-17', '''THERE IS NO OSHA STANDARD FOR THIS'' IS NOT AN ANSWER -- the GENERAL DUTY CLAUSE covers recognized hazards, and RECOGNITION is an element you build with every prior report. Put every threat and incident in writing to the employer, keep copies, and request their written prevention program, hazard assessment, and incident log. In states that mandate those documents, not having them is itself the violation. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-010 | pipeline: Workplace Violence] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 22f3eb4bc0d6803df4ebdd59f3c590f46cde8d79835387745114355855ffc9f5]', 'v1.0'),
('SAIS-PS-010-03', 'systemic_abuse_intelligence', 410, 'workplace_violence', 'workplace_violence_retaliation', 'federal + state', 'federal + state -- ALL_STATES', 'Retaliation Protections and the 30-Day OSHA Deadline', 'federal_agency | state_agency', 'workplace_violence_retaliation', 'https://www.whistleblowers.gov/', 'OSHA Whistleblower Protection Program: 800-321-6742 | EEOC: 800-669-4000 | Your state labor department | NLRB: 844-762-6572', 'OSH Act anti-retaliation (29 U.S.C. sec. 660(c)) -- 30-day filing deadline | OSHA whistleblower procedures (29 CFR Part 1977) | Title VII (42 U.S.C. sec. 2000e-3) | National Labor Relations Act sec. 7 and 8(a)(1) (29 U.S.C. sec. 157, 158) | State whistleblower and survivor employment protection statutes.', 'VERIFIED', '2026-08-17', 'THE OSHA RETALIATION DEADLINE IS 30 DAYS FROM THE RETALIATORY ACT. File it even if you are unsure -- it is free, requires no attorney, and can be done by phone. Then file the parallel tracks with longer clocks: EEOC at 180-300 days if a protected characteristic was involved, NLRB at 6 months if you acted with coworkers, and your state whistleblower statute, which frequently runs years. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-010 | pipeline: Workplace Violence] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: a1aed1d1f08789d255f75cd717f5c0391f1dc05bf1ce3cd384eb4e1672f757ac]', 'v1.0'),
('SAIS-PS-010-04', 'systemic_abuse_intelligence', 410, 'workplace_violence', 'workplace_violence_domestic_violence_intersection', 'federal + state', 'federal + state -- ALL_STATES', 'Domestic Violence That Follows the Worker -- Not a Private Matter', 'state_court | state_agency', 'workplace_violence_domestic_violence_intersection', 'https://www.thehotline.org/', 'National DV Hotline: 800-799-7233 | Text START to 88788 | Your state DV coalition -- see jurisdiction table | Your local court clerk', 'General Duty Clause (29 U.S.C. sec. 654(a)(1)) | Violence Against Women Act (34 U.S.C. sec. 12291) | State workplace violence restraining order statutes | State survivor employment leave and anti-discrimination statutes | State unemployment good-cause provisions.', 'VERIFIED', '2026-08-17', 'ASK WHETHER YOUR EMPLOYER CAN SEEK A WORKPLACE VIOLENCE RESTRAINING ORDER IN ITS OWN NAME -- many states allow it, it covers the workplace and coworkers, and it keeps the survivor out of the middle. Request safety accommodations IN WRITING, and if you later leave for safety reasons, state the domestic violence reason EXPLICITLY on the unemployment claim; most states treat it as good cause. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-010 | pipeline: Workplace Violence] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f2157408ecde7b13fa7e8028d4a9534e61d6c12beb904b7a57a35862bee1edab]', 'v1.0'),
('SAIS-PS-010-05', 'systemic_abuse_intelligence', 410, 'workplace_violence', 'workplace_violence_workers_compensation', 'state', 'state -- ALL_STATES', 'Workers'' Compensation -- Notice Deadlines and What Is Covered', 'state_agency', 'workplace_violence_workers_compensation', 'https://www.dol.gov/agencies/owcp', 'Your state workers'' compensation board -- see jurisdiction table | Your state labor department | HRSA health center locator: findahealthcenter.hrsa.gov', 'State workers'' compensation acts | State mental injury and PTSD coverage provisions | Longshore and Harbor Workers'' Compensation Act (33 U.S.C. sec. 901 et seq.) for covered maritime workers | Federal Employees'' Compensation Act (5 U.S.C. sec. 8101 et seq.) for federal employees.', 'VERIFIED', '2026-08-17', 'GIVE WRITTEN NOTICE TO THE EMPLOYER WITHIN DAYS -- the notice deadline is commonly 30 DAYS and late notice is a leading cause of denial. Get PSYCHOLOGICAL injury documented by a clinician early; many states cover it and delayed documentation is why those claims fail. And if the insurer invokes the ''purely personal assault'' exception, argue that employment CONDITIONS contributed -- public access, a known schedule, or prior notice to the employer that went unaddressed. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-010 | pipeline: Workplace Violence] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e2855090953aec8be94b807e3f9c5a631b307a1329f8c117ae8a4405df288cc4]', 'v1.0'),
('SAIS-PS-010-06', 'systemic_abuse_intelligence', 410, 'workplace_violence', 'workplace_violence_other_remedies', 'federal + state', 'federal + state -- ALL_STATES', 'Other Recovery Routes -- Third-Party Liability, Discrimination Claims, and Union Remedies', 'state_court | federal_agency | labor_organization', 'workplace_violence_other_remedies', 'https://www.lawhelp.org/', 'Your state bar lawyer referral service | EEOC: 800-669-4000 | NLRB: 844-762-6572 | Your union steward or business agent', 'Workers'' compensation exclusivity and its exceptions (state-specific) | Title VII (42 U.S.C. sec. 2000e) | National Labor Relations Act (29 U.S.C. sec. 157, 158) | Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | State premises liability and tort claims acts.', 'VERIFIED', '2026-08-17', 'LOOK PAST YOUR EMPLOYER TO A THIRD PARTY -- comp exclusivity bars claims against the employer but NOT against a property owner, staffing agency, client company, or security contractor whose failure enabled the attack. That is frequently the only solvent defendant. SEND THE PRESERVATION DEMAND TODAY for video, access logs, and prior complaints about the same person; those records are the case and they are retained for weeks. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-010 | pipeline: Workplace Violence] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 231ae29d36d8855e38cf9e34bf0ec4492d0c03ee4fc8602cb40118adf26aad6f]', 'v1.0'),
('SAIS-PS-011-01', 'systemic_abuse_intelligence', 411, 'cyberstalking', 'cyberstalking_evidence_capture', 'federal', 'federal -- NATIONWIDE', 'Evidence Capture -- The Step That Must Come Before Every Other Step', 'law_enforcement | technology_platform', 'cyberstalking_evidence_capture', 'https://www.ic3.gov/', 'FBI IC3: ic3.gov | Local law enforcement | National DV Hotline (tech safety): 800-799-7233 | VictimConnect: 855-484-2846', 'Preservation of stored records (18 U.S.C. sec. 2703(f)) | Stored Communications Act (18 U.S.C. sec. 2701 et seq.) | Interstate stalking including electronic (18 U.S.C. sec. 2261A(2)) | State cyberstalking and electronic harassment statutes.', 'VERIFIED', '2026-08-17', 'CAPTURE BEFORE YOU BLOCK, REPORT, OR DELETE. Screenshot with the display name, handle, timestamp, and URL visible in the SAME FRAME, and use the platform''s own DATA EXPORT where it exists -- exported records carry metadata that screenshots do not. Store it somewhere the person cannot reach, and keep a second backup. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-011 | pipeline: Cyberstalking] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: becad1112024fee3cea5cba1e5ff6966d25dcae0149f72bccc95a7e0bdbdfd57]', 'v1.0'),
('SAIS-PS-011-02', 'systemic_abuse_intelligence', 411, 'cyberstalking', 'cyberstalking_criminal_framework', 'federal + state', 'federal + state -- ALL_STATES', 'The Criminal Framework -- Cyberstalking Is Charged, Not Merely Complained About', 'law_enforcement | federal_agency', 'cyberstalking_criminal_framework', 'https://www.justice.gov/criminal/criminal-ceos/cyberstalking', '911 for immediate danger | FBI IC3: ic3.gov | Local law enforcement | Your FBI field office', 'Interstate stalking, electronic prong (18 U.S.C. sec. 2261A(2)) | Interstate communication of threats (18 U.S.C. sec. 875(c)) | Harassing communications (47 U.S.C. sec. 223) | Computer Fraud and Abuse Act (18 U.S.C. sec. 1030) | Wiretap Act (18 U.S.C. sec. 2511) | State cyberstalking and electronic harassment statutes.', 'VERIFIED', '2026-08-17', 'THE FEDERAL STATUTE REACHES CONDUCT CAUSING SUBSTANTIAL EMOTIONAL DISTRESS -- NOT ONLY FEAR OF BODILY INJURY. Say that when an officer tells you there is nothing to charge because no threat was made. Cite 18 U.S.C. sec. 2261A(2), ask for a supervisor, and file with IC3 independently of whatever the local agency decides. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-011 | pipeline: Cyberstalking] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 8e1d2b91621bab3d26ea02d5b1d9b1aa1bda6e6c02eff69a8c09df91c70c2baf]', 'v1.0'),
('SAIS-PS-011-03', 'systemic_abuse_intelligence', 411, 'cyberstalking', 'cyberstalking_platform_reporting', 'federal', 'federal -- NATIONWIDE', 'Platform Reporting -- Escalation Paths That Work Better Than the Report Button', 'technology_platform', 'cyberstalking_platform_reporting', 'https://cybercivilrights.org/', 'Cyber Civil Rights Initiative Crisis Helpline: 844-878-2274 | StopNCII.org for intimate image hashing | National DV Hotline: 800-799-7233', 'Section 230 (47 U.S.C. sec. 230) -- limits platform liability but does not prevent voluntary removal | Nonconsensual intimate image provisions (15 U.S.C. sec. 6851 civil cause of action) | State nonconsensual intimate image and online impersonation statutes | Platform terms of service.', 'VERIFIED', '2026-08-17', 'REPORT UNDER THE MOST SPECIFIC POLICY CATEGORY AND QUOTE THE PLATFORM''S OWN RULE -- generic ''harassment'' reports are triaged lowest. For intimate images use StopNCII.org, which hashes the image ON YOUR DEVICE without ever uploading it, so participating platforms can block matches proactively. And file SEARCH ENGINE DEINDEXING separately; it limits reach even when the host page stays up. [address_resolution: No physical address applies -- platform matters resolve online. For legal process, use the platform''s published law enforcement portal.] [doc_code: PS-011 | pipeline: Cyberstalking] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f5c6ccd7af4278ed0ba8c31fa9f8f11e763b3489610896fe2e001def83f36f8e]', 'v1.0'),
('SAIS-PS-011-04', 'systemic_abuse_intelligence', 411, 'cyberstalking', 'cyberstalking_doxxing_impersonation_image_abuse', 'federal + state', 'federal + state -- ALL_STATES', 'Doxxing, Impersonation, and Nonconsensual Intimate Images', 'federal_agency | state_court', 'cyberstalking_doxxing_impersonation_image_abuse', 'https://cybercivilrights.org/', 'Cyber Civil Rights Initiative Crisis Helpline: 844-878-2274 | NCMEC Take It Down (under 18) | FBI IC3: ic3.gov | VictimConnect: 855-484-2846', 'Federal civil cause of action for nonconsensual disclosure of intimate images (15 U.S.C. sec. 6851) | Interstate stalking (18 U.S.C. sec. 2261A(2)) | Interstate threats (18 U.S.C. sec. 875(c)) | State nonconsensual intimate image, online impersonation, and doxxing statutes | State data broker removal laws.', 'VERIFIED', '2026-08-17', 'FOR INTIMATE IMAGES, CALL 844-878-2274 AND SUBMIT TO STOPNCII.ORG -- and note there is a FEDERAL CIVIL CAUSE OF ACTION letting you sue for damages, with a limitations period far longer than most state claims. For doxxing, attack the SOURCE: data broker and people-search opt-outs, plus your state''s address confidentiality program. And nothing about having taken or consensually shared an image makes the distribution your fault. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-011 | pipeline: Cyberstalking] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 616bcf24f3c5e8f084a65a89ffc55589b140a4075057ef95818b423ccd13fbc2]', 'v1.0'),
('SAIS-PS-011-05', 'systemic_abuse_intelligence', 411, 'cyberstalking', 'cyberstalking_account_device_security', 'federal', 'federal -- NATIONWIDE', 'Account and Device Security -- Remediation in the Right Order', 'victim_advocate | technology_platform', 'cyberstalking_account_device_security', 'https://www.techsafety.org/', 'NNEDV Safety Net (tech safety): techsafety.org | National DV Hotline: 800-799-7233 | Local law enforcement', 'Computer Fraud and Abuse Act (18 U.S.C. sec. 1030) | Wiretap Act (18 U.S.C. sec. 2511) | Stored Communications Act (18 U.S.C. sec. 2701) | Interstate stalking, electronic (18 U.S.C. sec. 2261A(2)) | State spyware and electronic tracking statutes.', 'VERIFIED', '2026-08-17', 'CHANGE ACCOUNT RECOVERY SETTINGS, NOT JUST PASSWORDS -- recovery emails, phone numbers, backup codes, and trusted contacts pointing at the other person silently restore access after every reset, and that is why most lockouts fail. Start from a device they have never touched, make a NEW email the anchor, and plan the timing with an advocate: abrupt lockout announces discovery, and discovery is an escalation point. [address_resolution: Resolve via the state coalition''s local program directory; input = county. NOTE: shelter and safe-site addresses are CONFIDENTIAL and are never published -- the hotline arranges intake.] [doc_code: PS-011 | pipeline: Cyberstalking] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 41149bc80912efdb0418c91a5ff78b47c34d474209bcb8a91e27943af6c2a331]', 'v1.0'),
('SAIS-PS-011-06', 'systemic_abuse_intelligence', 411, 'cyberstalking', 'cyberstalking_orders_and_institutional_remedies', 'federal + state', 'federal + state -- ALL_STATES', 'Protection Orders, Schools and Employers, and Victim Compensation', 'state_court | state_agency', 'cyberstalking_orders_and_institutional_remedies', 'https://www.womenslaw.org/', 'Your local court clerk | Your school''s Title IX office | Your state crime victim compensation program | VictimConnect: 855-484-2846', 'Full faith and credit for protection orders (18 U.S.C. sec. 2265) | Title IX (20 U.S.C. sec. 1681; 34 CFR Part 106) | Clery Act and VAWA campus provisions (20 U.S.C. sec. 1092(f)) | Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | State stalking and civil harassment order statutes.', 'VERIFIED', '2026-08-17', 'ASK FOR ELECTRONIC-SPECIFIC RELIEF IN THE ORDER BY NAME -- no contact by any electronic means, no posting about you, no accounts in your name, no contacting your employer or family, and a bar on surveillance. Standard forms omit most of it. And if the person is ANONYMOUS, that is not a dead end: a civil filing against an unnamed defendant unlocks subpoena power to identify the account holder. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-011 | pipeline: Cyberstalking] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 8db222fcfd2d71b6fcfef1782664671b7fde4f6ccf14284cb1ef9883c646188d]', 'v1.0')
ON CONFLICT (resource_id) DO NOTHING RETURNING resource_id) SELECT count(*) AS inserted FROM ins